 JTable extTable(Component c){if(c instanceof JTable t&&t.isShowing())for(int r=0;r<t.getRowCount();r++)for(int k=0;k<t.getColumnCount();k++)if(Objects.toString(t.getValueAt(r,k),"").equals("Burp Workbench KR 0.6.0"))return t;if(c instanceof Container co)for(Component child:co.getComponents()){JTable t=extTable(child);if(t!=null)return t;}return null;}
