 String proxyGet(String path)throws Exception{try(Socket s=new Socket("127.0.0.1",8080)){s.setSoTimeout(10000);s.getOutputStream().write(("GET "+base+path+" HTTP/1.1\r\nHost: 127.0.0.1:19088\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));return new String(s.getInputStream().readAllBytes(),StandardCharsets.UTF_8);}}
