 boolean has(String model,int col,String value)throws Exception{var m=(DefaultTableModel)f(model);for(int r=0;r<m.getRowCount();r++)if(Objects.toString(m.getValueAt(r,col),"").contains(value))return true;return false;}
 void snapshot(String name)throws Exception{edt(()->{for(Window w:Window.getWindows())if(w instanceof Frame&&w.isVisible()){w.setBounds(0,0,1600,1000);w.validate();}});Thread.sleep(250);ImageIO.write(new Robot().createScreenCapture(new Rectangle(0,0,1600,1000)),"png",out.resolve(name).toFile());}
