  edt(()->{try{((JTextField)f("registry")).setText(base+"/api/js-miner/registry");((JButton)f("checkNpm")).doClick();}catch(Exception e){throw new RuntimeException(e);}});waitIdle();ok("registry present package status",has("dependencyModel",3,"등록됨"));ok("registry missing package remains unconfirmed candidate",has("dependencyModel",3,"미등록/비공개 후보"));ok("registry rate limit is inconclusive",has("dependencyModel",3,"조회 제한"));ok("registry 200 soft error is not registered",has("dependencyModel",3,"응답 형식 미확인"));ok("registry redirect is not followed",has("dependencyModel",3,"리다이렉트"));
  snapshot("actual-burp-js-miner.png");
  proxyGet("/assets/js-miner-inline.js");waitIdle();select("/assets/js-miner-inline.js");ok("inline base64 source map recovered via real Proxy History",((DefaultTableModel)f("recoveredModel")).getRowCount()==2);ok("inline original hidden API automatically found",has("endpoints",0,"/api/community/internal/reports"));
  proxyGet("/assets/js-miner-guess.js");waitIdle();select("/assets/js-miner-guess.js");edt(()->{try{((JButton)f("discoverMaps")).doClick();}catch(Exception e){throw new RuntimeException(e);}});waitIdle();ok("common .js.map location guessed and original recovered",((DefaultTableModel)f("recoveredModel")).getRowCount()==2);
  proxyGet("/assets/js-miner-invalid.js");waitIdle();select("/assets/js-miner-invalid.js");edt(()->{try{((JButton)f("discoverMaps")).doClick();}catch(Exception e){throw new RuntimeException(e);}});waitIdle();ok("invalid JSON source map reported without original invention",((DefaultTableModel)f("recoveredModel")).getRowCount()==0&&has("mapModel",1,"오류"));
  proxyGet("/assets/js-miner-cross.js");waitIdle();select("/assets/js-miner-cross.js");edt(()->{try{((JButton)f("discoverMaps")).doClick();}catch(Exception e){throw new RuntimeException(e);}});waitIdle();ok("cross-origin reference remains unrequested",has("mapModel",1,"발견 · 요청 전"));
  proxyGet("/assets/js-miner-redirect.js");waitIdle();select("/assets/js-miner-redirect.js");edt(()->{try{((JButton)f("discoverMaps")).doClick();}catch(Exception e){throw new RuntimeException(e);}});waitIdle();ok("source-map redirect recorded without follow",has("mapModel",1,"HTTP 302"));
