  Path dumpDir=out.resolve("dump");Files.createDirectories(dumpDir);edt(()->{javax.swing.Timer t=new javax.swing.Timer(100,event->{for(Window w:Window.getWindows()){JFileChooser chooser=chooser(w);if(chooser!=null){chooser.setSelectedFile(dumpDir.toFile());chooser.approveSelection();((javax.swing.Timer)event.getSource()).stop();return;}}});t.start();try{((JButton)f("dumpFiles")).doClick();}catch(Exception e){throw new RuntimeException(e);}});waitIdle();Path dumped;try(var list=Files.list(dumpDir)){dumped=list.filter(Files::isDirectory).findFirst().orElseThrow();}ok("native save dialog writes static file dump and manifest",Files.exists(dumped.resolve("manifest.tsv")));try(var walk=Files.walk(dumpDir)){ok("recovered traversal filenames stay inside dump directory",walk.filter(Files::isRegularFile).anyMatch(p->p.getFileName().toString().endsWith("private-community.js"))&&!Files.exists(out.resolve("outside/private-community.js")));}
  snapshot("actual-burp-js-miner-final.png");
  edt(()->{for(Window w:Window.getWindows())tab(w,"Extensions");});Thread.sleep(200);edt(()->{for(Window w:Window.getWindows()){var table=extTable(w);if(table!=null)for(int r=0;r<table.getRowCount();r++)for(int c=0;c<table.getColumnCount();c++)if(Objects.toString(table.getValueAt(r,c),"").equals("Burp Workbench KR 0.6.0")){table.setRowSelectionInterval(r,r);return;}}});edt(()->{javax.swing.Timer confirm=new javax.swing.Timer(100,event->{for(Window w:Window.getWindows())if(w instanceof JDialog&&w.isVisible()){JButton yes=button(w,"Yes");if(yes!=null){yes.doClick();((javax.swing.Timer)event.getSource()).stop();}}});confirm.start();for(Window w:Window.getWindows()){JButton remove=button(w,"Remove");if(remove!=null){remove.doClick();return;}}});Thread.sleep(800);ok("native extension unload closes JS history worker",((AtomicBoolean)f("closed")).get());log("LIVE_VALIDATION_FINISHED passed="+checks);
